questions.solution:
function limit(fn, max) {
  let calls = 0;
  return (...args) => {
    if (calls >= max) return "limit reached";
    calls += 1;
    return fn(...args);
  };
}

const login = limit((user) => `welcome ${user}`, 2);
console.log(login("ada"));
console.log(login("ada"));
console.log(login("ada"));

