questions.solution:
function once(fn) {
  let called = false;
  let result;
  return () => {
    if (!called) {
      called = true;
      result = fn();
    }
    return result;
  };
}

const init = once(() => {
  console.log("setup");
  return "ready";
});
const first = init();
const second = init();
console.log(first, second);

